effect.shader:
void main() {
    vec2 p = acScreenNorm - 0.5;
    float r = length(p);
    vec2 dir = (r > 1e-5) ? p / r : vec2(0.0);
    float k = pow(r * 2.0, power) * amount;

    int n = clamp(int(samples), 4, 32);
    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 32; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        soma += texture(inputImg, acScreenNorm - dir * k * t);
    }
    fragColor = soma / float(n + 1);
}
